#include "crashpad/pager.h"
#include <pthread.h>
#include <stdlib.h>

typedef struct {cp_page page;uint64_t id;size_t pins;unsigned char valid,referenced,dirty;} frame;
struct cp_buffer_pool {cp_blockdev*dev;frame*f;size_t n,hand;pthread_mutex_t mu;cp_wal_flush_fn flush;void*ctx;};
static cp_status write_frame(cp_buffer_pool*p,frame*f){if(!f->valid||!f->dirty)return CP_OK;uint64_t lsn=cp_page_chdr(&f->page)->lsn;if(p->flush){cp_status r=p->flush(p->ctx,lsn);if(r!=CP_OK)return r;}cp_status r=cp_page_write(p->dev,f->id,&f->page);if(r==CP_OK)r=cp_dev_sync(p->dev);if(r==CP_OK)f->dirty=0;return r;}
static cp_status victim(cp_buffer_pool*p,frame**out){for(size_t i=0;i<p->n;i++)if(!p->f[i].valid){*out=&p->f[i];return CP_OK;}for(size_t scans=0;scans<p->n*2;scans++){frame*f=&p->f[p->hand];p->hand=(p->hand+1)%p->n;if(f->pins)continue;if(f->referenced){f->referenced=0;continue;}cp_status r=write_frame(p,f);if(r!=CP_OK)return r;*out=f;return CP_OK;}return CP_E_NOMEM;}
cp_status cp_buffer_pool_create(cp_blockdev*d,size_t n,cp_wal_flush_fn fn,void*ctx,cp_buffer_pool**out){if(!d||!n||!out||n>SIZE_MAX/sizeof(frame))return CP_E_RANGE;cp_buffer_pool*p=calloc(1,sizeof(*p));if(!p)return CP_E_NOMEM;p->f=calloc(n,sizeof(*p->f));if(!p->f){free(p);return CP_E_NOMEM;}if(pthread_mutex_init(&p->mu,NULL)){free(p->f);free(p);return CP_E_IO;}p->dev=d;p->n=n;p->flush=fn;p->ctx=ctx;*out=p;return CP_OK;}
cp_status cp_buffer_pool_close(cp_buffer_pool*p){if(!p)return CP_E_RANGE;cp_status r=cp_buffer_pool_flush(p);if(r!=CP_OK)return r;pthread_mutex_destroy(&p->mu);free(p->f);free(p);return CP_OK;}
void cp_buffer_pool_destroy(cp_buffer_pool*p){if(!p)return;pthread_mutex_destroy(&p->mu);free(p->f);free(p);}
cp_status cp_buffer_pool_fetch(cp_buffer_pool*p,uint64_t id,cp_page**out){if(!p||!out)return CP_E_RANGE;pthread_mutex_lock(&p->mu);for(size_t i=0;i<p->n;i++)if(p->f[i].valid&&p->f[i].id==id){p->f[i].pins++;p->f[i].referenced=1;*out=&p->f[i].page;pthread_mutex_unlock(&p->mu);return CP_OK;}frame*f=NULL;cp_status r=victim(p,&f);if(r==CP_OK){r=cp_page_read(p->dev,id,&f->page);if(r==CP_OK){f->id=id;f->valid=1;f->pins=1;f->referenced=1;f->dirty=0;*out=&f->page;}}pthread_mutex_unlock(&p->mu);return r;}
cp_status cp_buffer_pool_new(cp_buffer_pool*p,uint64_t id,cp_page_type type,cp_page**out){if(!p||!out)return CP_E_RANGE;pthread_mutex_lock(&p->mu);for(size_t i=0;i<p->n;i++)if(p->f[i].valid&&p->f[i].id==id){pthread_mutex_unlock(&p->mu);return CP_E_RANGE;}frame*f=NULL;cp_status r=victim(p,&f);if(r==CP_OK){cp_page_init(&f->page,id,type);f->id=id;f->valid=1;f->pins=1;f->referenced=1;f->dirty=1;*out=&f->page;}pthread_mutex_unlock(&p->mu);return r;}
cp_status cp_buffer_pool_mark_dirty(cp_buffer_pool*p,uint64_t id,uint64_t lsn){if(!p)return CP_E_RANGE;pthread_mutex_lock(&p->mu);cp_status r=CP_E_RANGE;for(size_t i=0;i<p->n;i++)if(p->f[i].valid&&p->f[i].id==id){if(cp_page_hdr(&p->f[i].page)->lsn>lsn){r=CP_E_RANGE;break;}cp_page_hdr(&p->f[i].page)->lsn=lsn;p->f[i].dirty=1;p->f[i].referenced=1;r=CP_OK;break;}pthread_mutex_unlock(&p->mu);return r;}
cp_status cp_buffer_pool_unpin(cp_buffer_pool*p,uint64_t id){if(!p)return CP_E_RANGE;pthread_mutex_lock(&p->mu);cp_status r=CP_E_RANGE;for(size_t i=0;i<p->n;i++)if(p->f[i].valid&&p->f[i].id==id){if(!p->f[i].pins)r=CP_E_RANGE;else{p->f[i].pins--;r=CP_OK;}break;}pthread_mutex_unlock(&p->mu);return r;}
cp_status cp_buffer_pool_flush(cp_buffer_pool*p){if(!p)return CP_E_RANGE;pthread_mutex_lock(&p->mu);cp_status r=CP_OK;for(size_t i=0;i<p->n;i++){if(p->f[i].pins){r=CP_E_NOMEM;break;}r=write_frame(p,&p->f[i]);if(r!=CP_OK)break;}pthread_mutex_unlock(&p->mu);return r;}
